\u005f\u0049\u0021\u0051\u0061\u0065\u0051\u0038\u005d\u006a\u005c\u004f\u0063\u004f\u007c\u0022\u005d\u005b\u0032\u0045\u0064\u003e\u0031\u0028\u0022\u006f\u0068\u007b\u0043\u002a\u0025\u002c\u0072\u003e\u0071\u005e\u0037\u003d\u002b\u0070\u0024\u0067\u006a\u0061\u004a\u0047\u0062\u005b\u002e\u0075\u0055\u0068\u0056\u005d\u0047\u0023\u006c\u006c\u0026\u0037\u0045\u002f\u005a\u0057\u0050\u005c\u0047\u0052\u0062\u0027\u006d\u0078\u006d\u0027\u0064\u0050\u0035\u0033\u0039\u0054\u0064\u0046\u006e\u0060\u0053\u0022\u004e\u0071\u005a\u0055\u0032\u005c\u003e\u0057\u0064\u0074\u0022\u004c\u0030\u004c\u0055\u0079\u0057\u0046\u004c\u0048\u0047\u0049\u0027\u0068\u0052\u005c\u0065\u0066\u0054\u0067\u0039\u002c\u0041\u0029\u0066\u0067\u0028\u0061\u0033\u0022\u0030\u0053\u005c\u0071\u0056\u0068\u0047\u007d\u0035\u0077\u007d\u0051\u0052\u007c\u0079\u0063\u0028\u006a\u0050\u005c\u0045\u0033\u004a\u0062\u005f\u0038\u0029\u0072\u0025\u0051\u0028\u002a\u0020\u0066\u0055\u002c\u0058\u0063\u0073\u0024\u0041\u0043\u007b\u005b\u0042\u0038\u0077\u0032\u0073\u006e\u0053\u0070\u0051\u002c\u0058\u0072\u0037\u0020\u0026\u0059\u006e\u0077\u0038\u0041\u0049\u0058\u0053\u005a\u0032\u0039\u0042\u0021\u0055\u007a\u0064\u0062\u006c\u0059\u006f\u007b\u0051\u007e\u006d\u002a\u0040\u005c\u0064\u0048\u0054\u007b\u0060\u0021\u0026\u004d\u002c\u0050\u0072\u0034\u006d\u0054\u0061\u0041\u0052\u0064\u0044\u0077\u0024\u0078\u002f\u0034\u0048\u0032\u0069\u0067\u0065\u004b\u006e\u0046\u0058\u0060\u006d\u002d\u005a\u0052\u0064\u0057\u002c\u0061\u0053\u0071\u0067\u0039\u007d\u007d\u0029\u0048\u0023\u0064\u0026\u0054\u0059\u0038\u0059\u002d\u0022\u0052\u005c\u0058\u0053\u0023\u0061\u0034\u005f\u005f\u004a\u004a\u0056\u0060\u004e\u0036\u0040\u0064\u0035\u006f\u0058\u0076\u007b\u005b\u0077\u0021\u0066\u006e\u0050\u0029\u0073\u003b\u0021\u0063\u0039\u0033\u0022\u0060\u0079\u0031\u0076\u0045\u0031\u002a\u0057\u007b\u004f\u002b\u0070\u005a\u004d\u0076\u0022\u0067\u0077\u002a\u0079\u003c\u0035\u003e\u0036\u006a\u002e\u0043\u005b\u0077\u0070\u007d\u005e\u0034\u0023\u0042\u0042\u004b\u0022\u007e\u006d\u0069\u0061\u006a\u0050\u0027\u006f\u006b\u007b\u0062\u0026\u0023\u0073\u0049\u0062\u0072\u0050\u004d\u0053\u006f\u0069\u0034\u0069\u0055\u006a\u0078\u0022\u004d\u0075\u0045\u005e\u002c\u0062\u004a\u0068\u0064\u0028\u0060\u006f\u0028\u0064\u0023\u0027\u004d\u0063\u002d\u0020\u0040\u0033\u0035\u0021\u005e\u0057\u002b\u0051\u003c\u0041\u0040\u0062\u0058\u005a\u002f\u0073\u006b\u002b\u006f\u0026\u0035\u003d\u004d\u0054\u0048\u0023\u0044\u0064\u0074\u005d\u0045\u005a\u0069\u0048\u005b\u0026\u007c\u0058\u0056\u006f\u005b\u006a\u0031\u0067\u0070\u004d\u0049\u007e\u0032\u0025\u002e\u0065\u0033\u007d\u0035\u002d\u0021\u004d\u0039\u007e\u0025\u0043\u0050\u003c\u0061\u004b\u0057\u0068\u006d\u0061\u0065\u005b\u0055\u004c\u005c\u004a\u003d\u0058\u004d\u0072\u0070\u0028\u005a\u0045\u003c\u0054\u0041\u0031\u0056\u0076\u002a\u007d\u0054\u0030\u007a\u003a\u0039\u0051\u006a\u004c\u0043\u0052\u0071\u003a\u003d\u0028\u0040\u003b\u0023\u0032\u0074\u0064\u0040\u0051\u0040\u0076\u0061\u0069\u0067\u003d\u0055\u002e\u006e\u0029\u0026\u0057\u006c\u005a\u002e\u005a\u002c\u0040\u005e\u0072\u0039\u005f\u0022\u004e\u0066\u003b\u005b\u0076\u005f\u005e\u0051\u004e\u007c\u0075\u0074\u0030\u0072\u003c\u0029\u003f\u0068\u0038\u0026\u0038\u0031\u0065\u0051\u0052\u0074\u0049\u0043\u0042\u0075\u0028\u0070\u003c\u0075\u0077\u0077\u0066\u0071\u0072\u0072\u006d\u004f\u005f\u0026\u004f\u0074\u0049\u0037\u005a\u007e\u0058\u0033\u0043\u007c\u0054\u0073\u0067\u0027\u0070\u003b\u0050\u0029\u0022\u0063\u0068\u002d\u002b\u0039\u0063\u0027\u0071\u0057\u0033\u0070\u0070\u002d\u0042\u004e\u002c\u0070\u0039\u0073\u0021\u0050\u0068\u004e\u007c\u0024\u0055\u0061\u0070\u005a\u0064\u002b\u0073\u0042\u0034\u003c\u0077\u006b\u0070\u0063\u0065\u0051\u004b\u003b\u0065\u0042\u007a\u0041\u003a\u0044\u0057\u0079\u0055\u0040\u0079\u003c\u0071\u0055\u0032\u0068\u006e\u0025\u0042\u0061\u0065\u0047\u002b\u006f\u002c\u0041\u0029\u005c\u0059\u0072\u005c\u005b\u0040\u0057\u007a\u004d\u0044\u0061\u0037\u0025\u005c\u0020\u003d\u0068\u0072\u007d\u002a\u003f\u004e\u004b\u004a\u0058\u003f\u003b\u003f\u0021\u003a\u006c\u0074\u0064\u003a\u0020\u0041\u007e\u0034\u0052\u004f\u0078\u002b\u0024\u004a\u0069\u0025\u0049\u003f\u0038\u007b\u0036\u0060\u0035\u0058\u0050\u004b\u0070\u002f\u0070\u005c\u0043\u007c\u0055\u0036\u0020\u004d\u0036\u006a\u0036\u005b\u0027\u0056\u006c\u0021\u0078\u002d\u002b\u0031\u0065\u0060\u005e\u0040\u0057\u002b\u002f\u006d\u004a\u0048\u0052\u0059\u0060\u0060\u0043\u0060\u0058\u006f\u0050\u0038\u006d\u0049\u0076\u0073\u0037\u004d\u006f\u006b\u0062\u007b\u004a\u002f\u0041\u007b\u0052\u0054\u0067\u002d\u006f\u003a\u0049\u0032\u0066\u0064\u0052\u004c\u0063\u0032\u0039\u002d\u006f\u0040\u0053\u002b\u0078\u0065\u005d\u006f\u006d\u004f\u003b\u003d\u0033\u0022\u0074\u007e\u0025\u0024\u005d\u004e\u0048\u0072\u0023\u0057\u004d\u0061\u0059\u0044\u0050\u002f\u0049\u0055\u004f\u004f\u0065\u0064\u0039\u0031\u0058\u0037\u0035\u0032\u007b\u0065\u004a\u0072\u007e\u0046\u002c\u0041\u0040\u005a\u0021\u0026\u0031\u005f\u0044\u004f\u0042\u0053\u0048\u005d\u0041\u0030\u007a\u0067\u006e\u005d\u005d\u0041\u0069\u0055\u0032\u006b\u0068\u0025\u007e\u0025\u004f\u002b\u007e\u0028\u005d\u005d\u0076\u004f\u002a\u0063\u0023\u005a\u0061\u007b\u0052\u0036\u002a\u0026\u0055\u0046\u0068\u0061\u0035\u0071\u004d\u003a\u0053\u003a\u003a\u0041\u0025\u007b\u0066\u002a\u0079\u0079\u0066\u005e\u003c\u003b\u0037\u0052\u003b\u0036\u006c\u002b\u0032\u004a\u0067\u0042\u0066\u004a\u002d\u0038\u006b\u006f\u0041\u0023\u007d\u002c\u004e\u002f\u003f\u0035\u002b\u0027\u002f\u0032\u0039\u005e\u0068\u0027\u004f\u007e\u0060\u0037\u0052\u0027\u006f\u0021\u0061\u0049\u0045\u007a\u0059\u0031\u002a\u0030\u004b\u003b\u0039\u0027\u0045\u003d\u0026\u0033\u006d\u0077\u004e\u005c\u0033\u0032\u0022\u0038\u0070\u0041\u0023\u005d\u0066\u0042\u002b\u0071\u0027\u0037\u003c\u0042\u0078\u0031\u0078\u002a\u0068\u0056\u0053\u0052\u0053\u0067\u007d\u0048\u0036\u0062\u0059\u0077\u0022\u003c\u0075\u005e\u0029\u0040\u0077\u006f\u007b\u0066\u0068\u0067\u0036\u005e\u0061\u0028\u0061\u0069\u0023\u002f\u0025\u0051\u005c\u0055\u0049\u0035\u002b\u003a\u004d\u0045\u0073\u003b\u005d\u004e\u0044\u0028\u0070\u0059\u004b\u003f\u0077\u0024\u003c\u002c\u0052\u006f\u0079\u003e\u0076\u0037\u0062\u0072\u0043\u0050\u007b\u004d\u005f\u006f\u0059\u004b\u0026\u0068\u0066\u002c\u002d\u0050\u0078\u004e\u0032\u0076\u003e\u0054\u007e\u0047\u0030\u0051\u0020\u0068\u003e\u0051\u0023\u0079\u0022\u006b\u003e\u0053\u005f\u0041\u006e\u0052\u0077\u0036\u003c\u0033\u005e\u0034\u004b\u005d\u0023\u0058\u0074\u0052\u0045\u005e\u007a\u0062\u0056\u0040\u0052\u002b\u0035\u002c\u0020\u0064\u0079\u003f\u004b\u002b\u006b\u0041\u0077\u0074\u006f\u0065\u0061\u0068\u0038\u0053\u0025\u0031\u0065\u0072\u0070\u0060\u0055\u0072\u002d\u0052\u0044\u002e\u0035\u0043\u006c\u0022\u0055\u006f\u0029\u002c\u004a\u0070\u0021\u004a\u003f\u0039\u006b\u0048\u0047\u0064\u0035\u0071\u0043\u0075\u005f\u0027\u004c\u007b\u0062\u0044\u0065\u002e\u0075\u0074\u0024\u004f\u002f\u0024\u004d\u005f\u006f\u002d\u006c\u004f\u0072\u006b\u0050\u0031\u0050\u0025\u0061\u005b\u0021\u0037\u005c\u0045\u0074\u004a\u005e\u0028\u0021\u0030\u0068\u002b\u003b\u0033\u0038\u0022\u0074\u006b\u0033\u002f\u006a\u0041\u0075\u0052\u004a\u0026\u0047\u0051\u0025\u0063\u0021\u005b\u003f\u0062\u006a\u0039\u0038\u0075\u0027\u0026\u0026\u0060\u003b\u006c\u003b\u007a\u006a\u007c\u0063\u006e\u0024\u0052\u0023\u0043\u0022\u0070\u007c\u0060\u006d\u0038\u0025\u0078\u0026\u0021\u002b\u0063\u0051\u006b\u0042\u0034\u006b\u002a\u003c\u0043\u0048\u0037\u0022\u0043\u0034\u0060\u003c\u0022\u0071\u003d\u0029\u0035\u0028\u0065\u004a\u007c\u003b\u0028\u002a\u0039\u006c\u004b\u002c\u0078\u006e\u0044\u007e\u002e\u0051\u003d\u0038\u0021\u004a\u006e\u004e\u0044\u0053\u004b\u002e\u0060\u0029\u0067\u0071\u006f\u0059\u0061\u0044\u005e\u007c\u006a\u0056\u005d\u0061\u0077\u005b\u0073\u0075\u0037\u0025\u0043\u0064\u004f\u0031\u007c\u005c\u004b\u0030\u0074\u007a\u003e\u004c\u0063\u007c\u004c\u003c\u0051\u0065\u0032\u0066\u005a\u0030\u004a\u007d\u006b\u006c\u0022\u0040\u005e\u0079\u007a\u002e\u0048\u0021\u003d\u0065\u0040\u0076\u0075\u0050\u003c\u0078\u006c\u004c\u0075\u0054\u0052\u0035\u0070\u0063\u0064\u004c\u0043\u0027\u0070\u0048\u006d\u005f\u0031\u0028\u007a\u0033\u0046\u003c\u002e\u005e\u0021\u0055\u003c\u002f\u0031\u0070\u0036\u0041\u0029\u0057\u005e\u007c\u005d\u0064\u0033\u002f\u0042\u007c\u006a\u0050\u0036\u0066\u0070\u0053\u0064\u002e\u005b\u006a\u0022\u0033\u0046\u007b\u0038\u0074\u0042\u0057\u003f\u003d\u002c\u003e\u0043\u0048\u003d\u0022\u0076\u0054\u0036\u0021\u006a\u004a\u0052\u002b\u005f\u006e\u003b\u0033\u0039\u0035\u0060\u005a\u0074\u004f\u0045\u0047\u0033\u0048\u002f\u0070\u0073\u0074\u0034\u0064\u0065\u0060\u0020\u0032\u0055\u002f\u0043\u0076\u002a\u0038\u0034\u0039\u0066\u0060\u0065\u0029\u0071\u002a\u0021\u005e\u0076\u006a\u005e\u0029\u0055\u0032\u005c\u004c\u0041\u003e\u0026\u004c\u006e\u0045\u0021\u007e\u0060\u007a\u005d\u0073\u0057\u0046\u0069\u0033\u002e\u0071\u006b\u0053\u002e\u0046\u0032\u006a\u006c\u006c\u0079\u004a\u0032\u0044\u007b\u003b\u0034\u0054\u002b\u0054\u0060\u004c\u0079\u0074\u0049\u0040\u0046\u0064\u0046\u0055\u0063\u0045\u0062\u0037\u0055\u0033\u007d\u003b\u0050\u0051\u0028\u0077\u0036\u0028\u007e\u0048\u0065\u002a\u0076\u003b\u005e\u0021\u003f\u002b\u006b\u0053\u005d\u0020\u002b\u003a\u0022\u0030\u0027\u0035\u002b\u0025\u0052\u0077\u0038\u0055\u0031\u004f\u0065\u0062\u006c\u0052\u0051\u003b\u0038\u0055\u005d\u006c\u004a\u0068\u0059\u0040\u004a\u0039\u005c\u0063\u0022\u0049\u007b\u0058\u006f\u0074\u0034\u0034\u002b\u002f\u005f\u003f\u006f\u0031\u0030\u0029\u0026\u0038\u003e\u004d\u0065\u0062\u0044\u006f\u005d\u0070\u0068\u0072\u005d\u006e\u004a\u007b\u0046\u0022\u003e\u004d\u0039\u0058\u0067\u006c\u0052\u0061\u0021\u005a\u006b\u0041\u003b\u0066\u0076\u005a\u0024\u006c\u0063\u0065\u0052\u0067\u0038\u0059\u0073\u0077\u0079\u0037\u0023\u005f\u0020\u0025\u007b\u006c\u0050\u0064\u003e\u0022\u0029\u004c\u005a\u0052\u006b\u004a\u0067\u0041\u005c\u002f\u003b\u003a\u0022\u0051\u002d\u0078\u003d\u0020\u0060\u0035\u0078\u0039\u0044\u003d\u0020\u0072\u0071\u0034\u0039\u004b\u0042\u0025\u002d\u0057\u003f\u003c\u004f\u003c\u0065\u0079\u0040\u0040\u0055\u0063\u0040\u0033\u0039\u003f\u005c\u0051\u007d\u0063\u0057\u0057\u0025\u0032\u0073\u0056\u0026\u0028\u0030\u0077\u002f\u0039\u0042\u0029\u0047\u0072\u0025\u0073\u006a\u0045\u003e\u004b\u0062\u0043\u0039\u0058\u003f\u003c\u0068\u0041\u0034\u0027\u0078\u0042\u0040\u0034\u0075\u0037\u0078\u0045\u0032\u0041\u006e\u007c\u0067\u0061\u002a\u006a\u0043\u005f\u004b\u0034\u002d\u006b\u005f\u0037\u0058\u0031\u005a\u0073\u0051\u0037\u0050\u0056\u005a\u0059\u003f\u0064\u0022\u0035\u006f\u0043\u0020\u0036\u0043\u0024\u003d\u007d\u0050\u002a\u005b\u0073\u0045\u0058\u004e\u004d\u0075\u004d\u004e\u0032\u002f\u0056\u0032\u005b\u005c\u0032\u0066\u0058\u003e\u0070\u0048\u0057\u0022\u0074\u003a\u0068\u006e\u0032\u0030\u0069\u004b\u0073\u0045\u0077\u003d\u003c\u002d\u0029\u004a\u0059\u0077\u0038\u003c\u0021\u0021\u007a\u0060\u007a\u002f\u002f\u004e\u0026\u0054\u0049\u0077\u0067\u0038\u0049\u006a\u004d\u0058\u005c\u0020\u002f\u0072\u003f\u004a\u0059\u0022\u0039\u0034\u0036\u0041\u0076\u007c\u0071\u0050\u007e\u0057\u0058\u004c\u0025\u0052\u003b\u0020\u003b\u004f\u0026\u0060\u0041\u003b\u0037\u0064\u002d\u0028\u002e\u0021\u0040\u0028\u0041\u0026\u0037\u006a\u0045\u0076\u0072\u0061\u0034\u005d\u007b\u0057\u006d\u006c\u0054\u0034\u0065\u0058\u0036\u005d\u0030\u005a\u007a\u004d\u0047\u0030\u0029\u006a\u007e\u0064\u0022\u006e\u0072\u0070\u006d\u0054\u006f\u0023\u0077\u0045\u006c\u0033\u0076\u006e\u0061\u0065\u003e\u003d\u002b\u003c\u0030\u006e\u0042\u005a\u0039\u007d\u0038\u0042\u0052\u0051\u0049\u0029\u0041\u007a\u006f\u005b\u004e\u0044\u005b\u003e\u005e\u0045\u0076\u0070\u0020\u004b\u005e\u0068\u0043\u002b\u004b\u006f\u0077\u006f\u0075\u0078\u0053\u006b\u0045\u006a\u0030\u0032\u0048\u0075\u0079\u005c\u0047\u0075\u0021\u0038\u004d\u0041\u0036\u0035\u0038\u003c\u0050\u0064\u0071\u006b\u0020\u004c\u0049\u005d\u004b\u0024\u0072\u006d\u0065\u0034\u0049\u004b\u0022\u005e\u005b\u0074\u0024\u0074\u005d\u005b\u0046\u002d\u0055\u0021\u0069\u0045\u0048\u002d\u0058\u0027\u0076\u0024\u0066\u003e\u007e\u007d\u0025\u0044\u004a\u0068\u0061\u0033\u006e\u0022\u0025\u0020\u0056\u006f\u005d\u0022\u003c\u0042\u007a\u0044\u0054\u0035\u002b\u0052\u0050\u003f\u0031\u003c\u0077\u0077\u006c\u0042\u0063\u006b\u0029\u005e\u0068\u005b\u002c\u0051\u0045\u0025\u0031\u0031\u003e\u0049\u004b\u0030\u0025\u0059\u0030\u002c\u002b\u004b\u0078\u003a\u004c\u0063\u003a\u0052\u006f\u006d\u003c\u0027\u0023\u0050\u0063\u0021\u007d\u0042\u002e\u0072\u0075\u003c\u005a\u0042\u007c\u004a\u007e\u005c\u0032\u003d\u0053\u007e\u0056\u006c\u0021\u002b\u004d\u0071\u0028\u0070\u0023\u0049\u0057\u0033\u0025\u0074\u0033\u0061\u0034\u005e\u0074\u003b\u0072\u0048\u0063\u003d\u0076\u0073\u0038\u002f\u0057\u0020\u0074\u0035\u0021\u005a\u003e\u003f\u0042\u002a\u002a\u0050\u005c\u002f\u0047\u0022\u005f\u0039\u0024\u0040\u0045\u0077\u0046\u007d\u005f\u005b\u003c\u0075\u002d\u004d\u0032\u0024\u0079\u0070\u0023\u0045\u005e\u0037\u003b\u005c\u007e\u0051\u0048\u0037\u002b\u005d\u005a\u0077\u0066\u0047\u0038\u0060\u0042\u0050\u0077\u003e\u0053\u0020\u0025\u003b\u0073\u0021\u0045\u0067\u0034\u007d\u0030\u0075\u0077\u0070\u0053\u0069\u003e\u006d\u0034\u0059\u002a\u006d\u004a\u0069\u0040\u002b\u002c\u003f\u0052\u0035\u0058\u0045\u0067\u002d\u0048\u0028\u0037\u002c\u0028\u007b\u0036\u0071\u005a\u0067\u0068\u005c\u006c\u0035\u0024\u0053\u0061\u004a\u0076\u0074\u0077\u003d\u003a\u006f\u007b\u0063\u0036\u0032\u0030\u0063\u007c\u0049\u0023\u0043\u0053\u0063\u0036\u004b\u0050\u0041\u003f\u002c\u0042\u0073\u0056\u007c\u002d\u0022\u004b\u004d\u0046\u003a\u0041\u0028\u006e\u0057\u0037\u0059\u0054\u0077\u0052\u003d\u004c\u003c\u006f\u0032\u003c\u0063\u0060\u002b\u0026\u006d\u0043\u003e\u0064\u0071\u0035\u0041\u0022\u0050\u0079\u0038\u0026\u0059\u0028\u003f\u0056\u0042\u004c\u0020\u0063\u0057\u004a\u0033\u006f\u0061\u0055\u0034\u002d\u006d\u0054\u0059\u0052\u004a\u0043\u0068\u0030\u002b\u002f\u002d\u0041\u0037\u0066\u004d\u0064\u0034\u007c\u0074\u007b\u0059\u0048\u0030\u007c\u0049\u0042\u0059\u0064\u0031\u007d\u0078\u002c\u002a\u004d\u0061\u0029\u006a\u0064\u0026\u003d\u0020\u0067\u003b\u003e\u0079\u002c\u0023\u0047\u006e\u0075\u0026\u002d\u0056\u0051\u0049\u0040\u0066\u0054\u005e\u0078\u0047\u0033\u006f\u0074\u0072\u005e\u007a\u007e\u0046\u003c\u0034\u0072\u006a\u007b\u004a\u0066\u0036\u003f\u0040\u0074\u0035\u0065\u0072\u0073\u0078\u005f\u0073\u0022\u0062\u004e\u004b\u0039\u007d\u0032\u003c\u0022\u0059\u0068\u004c\u005e\u0079\u0058\u002a\u0079\u004c\u005a\u0026\u006d\u0064\u0054\u0060\u006c\u006c\u0059\u002e\u004a\u0055\u0025\u0073\u0038\u0030\u003d\u0031\u0043\u0057\u0034\u004c\u0060\u006d\u0050\u0041\u007d\u0064\u004f\u0036\u0055\u0023\u0077\u003a\u003f\u0020\u005f\u0034\u0071\u002f\u0056\u0060\u0073\u002e\u0021\u0040\u0045\u0045\u004f\u0068\u0045\u007a\u0061\u0076\u0027\u004b\u005d\u006b\u006a\u0029\u007a\u0053\u0071\u0051\u004f\u002a\u0038\u0054\u0027\u005d\u0033\u005b\u004d\u0051\u0075\u0070\u0058\u002c\u004d\u006d\u0077\u0062\u0049\u006f\u006c\u005d\u0072\u003c\u0050\u0027\u0035\u0064\u0075\u0050\u0020\u003b\u004b\u0062\u0046\u0038\u0060\u006b\u0024\u004d\u0057\u0065\u003c\u0057\u0059\u0078\u0061\u002d\u002b\u0065\u0023\u005f\u0023\u0061\u0064\u0042\u002f\u0041\u0070\u0072\u0033\u0067\u0020\u0079\u004f\u0072\u0035\u002a\u007c\u0042\u0021\u0043\u003a\u0046\u0076\u0062\u007a\u0065\u0037\u005d\u0037\u004f\u007b\u004c\u007a\u007a\u0027\u006d\u0024\u006a\u0041\u0024\u0051\u0049\u0058\u0049\u0034\u0062\u002f\u0077\u007a\u0027\u0063\u0075\u0026\u0037\u0071\u005d\u002d\u002c\u007d\u0041\u005d\u003a\u003f\u0042\u0062\u0023\u0061\u0056\u0029\u007b\u0046\u0058\u0069\u006f\u0056\u0053\u0058\u002b\u0065\u0061\u0058\u003d\u0062\u0020\u0064\u002f\u005b\u0023\u005b\u0077\u005c\u0042\u0042\u0047\u007c\u0060\u0022\u0025\u007a\u0062\u006c\u0069\u0041\u0022\u003a\u0054\u003c\u002c\u0039\u007a\u0023\u0076\u0041\u0032\u0029\u006e\u007d\u0045\u0029\u002f\u0047\u003a\u0059\u005a\u0055\u002d\u0020\u0076\u004d\u0023\u0051\u0067\u0032\u0022\u002a\u0065\u0079\u0063\u0042\u004c\u0077\u0037\u002b\u0052\u002b\u0059\u004c\u0062\u0055\u0075\u0033\u0057\u0059\u006a\u0064\u0044\u0023\u007b\u005e\u0038\u0036\u0058\u002a\u004a\u0053\u0052\u0064\u0034\u0043\u0062\u005d\u0063\u004d\u003a\u0076\u0030\u0052\u0053\u0071\u0027\u003a\u0033\u0037\u0071\u002c\u005b\u0044\u003b\u0051\u0035\u004c\u0039\u0026\u0056\u006d\u005f\u0059\u0054\u0070\u004f\u002e\u0069\u007a\u006a\u0034\u0032\u0067\u005d\u0077\u0037\u0023\u0029\u002b\u0027\u003f\u0042\u0025\u0066\u0069\u0042\u0048\u007d\u0036\u007e\u0061\u0029\u0033\u006e\u0068\u005e\u0076\u0033\u003b\u004a\u005f\u0060\u0077\u004e\u0042\u0079\u0048\u005a\u004b\u005b\u005c\u0051\u004a\u007e\u0077\u004e\u005b\u0034\u0070\u0035\u0078\u0076\u0057\u0030\u0059\u006b\u0070\u0057\u003b\u003b\u0057\u0044\u003b\u0043\u006b\u002a\u0042\u0077\u0044\u007d\u006a\u004f\u007d\u0037\u0079\u0025\u003c\u0030\u007b\u004e\u0079\u0054\u007a\u002f\u004b\u006a\u0075\u003b\u0035\u002b\u004f\u0056\u0063\u0046\u0041\u004f\u002f\u003c\u004f\u002b\u0037\u002a\u0045\u0032\u0042\u006a\u0074\u006e\u0068\u0062\u0053\u004d\u004d\u0068\u0072\u0041\u004b\u004d\u0064\u004d\u006d\u0026\u0077\u006d\u002a\u0028\u004e\u0070\u0051\u0074\u005d\u002f\u0060\u0058\u0047\u0068\u004d\u0064\u0045\u0034\u002e\u0062\u0038\u003a\u0077\u003a\u005d\u007e\u003c\u0024\u0033\u0055\u0049\u0020\u0054\u0047\u0064\u0060\u0070\u0048\u006f\u004f\u0028\u0054\u0074\u005d\u0067\u0025\u0035\u0029\u006b\u0028\u0048\u0048\u005b\u0063\u0069\u0038\u0067\u0040\u0059\u0077\u0028\u003f\u0060\u0076\u004a\u0057\u004c\u005c\u0035\u0065\u0025\u0069\u003f\u004e\u0049\u0071\u0034\u002c\u003b\u0036\u005a\u0075\u0055\u0046\u0071\u005e\u003e\u0033\u0044\u0079\u003d\u005f\u0027\u0066\u0060\u004f\u0027\u006f\u0059\u003d\u0037\u0061\u005a\u0064\u0055\u0040\u0041\u0060\u004c\u0021\u0028\u003f\u0077\u004a\u0032\u0035\u0028\u004f\u003b\u0076\u0051\u0073\u0052\u002e\u005b\u0046\u007a\u002d\u004b\u0045\u003f\u0054\u0062\u006a\u007a\u005f\u003a\u002e\u0058\u0055\u005f\u002b\u0074\u0049\u0069\u004f\u0030\u006f\u0032\u0035\u007b\u0064\u007c\u0043\u002f\u0040\u003a\u0073\u0031\u005e\u0065\u0022\u0057\u0077\u0039\u007e\u0056\u0038\u003d\u0063\u0074\u0066\u0048\u005c\u0032\u007d\u004d\u006c\u005f\u0040\u003a\u0033\u007e\u0077\u0039\u0076\u0038\u007d\u0025\u0035\u0064\u006d\u0031\u0029\u0024\u0071\u004e\u0040\u0060\u0052\u0071\u0071\u0037\u007d\u0054\u0028\u0023\u0023\u0025\u0052\u0068\u002d\u002f\u0074\u0020\u0068\u0064\u0024\u0043\u004c\u0060\u0038\u0021\u0076\u0024\u0044\u0025\u0067\u005a\u0039\u0049\u006d\u0030\u006d\u006a\u0040\u0042\u0066\u0026\u0053\u004b\u0046\u005d\u003e\u0071\u002c\u002a\u003a\u0057\u0071\u0043\u0026\u0043\u0053\u0058\u004a\u0076\u0023\u0030\u002e\u007b\u003f\u002c\u003e\u0042\u0072\u0055\u0044\u0064\u0040\u0021\u004a\u0071\u0056\u0079\u0028\u005b\u0021\u005c\u0022\u0037\u0035\u004c\u0020\u0060\u006a\u006d\u0051\u0073\u0053\u0030\u0048\u0054\u004e\u0049\u0079\u0034\u0064\u005c\u0077\u002c\u003c\u0044\u0028\u005c\u005b\u0061\u0035\u004e\u006a\u0047\u0025\u003d\u002f\u0033\u0067\u0057\u002c\u0051\u004c\u0063\u0031\u006d\u0039\u0042\u0077\u0060\u0071\u005a\u0024\u0048\u005e\u006a\u0041\u0031\u0052\u0037\u0026\u0065\u004d\u0077\u005c\u0039\u0076\u0060\u0025\u0055\u0037\u0045\u007c\u0065\u006c\u0065\u0062\u004e\u0021\u0028\u004d\u003e\u0071\u0032\u002b\u0057\u007e\u0028\u0052\u0059\u0067\u0063\u0030\u005b\u0038\u0038\u0036\u004d\u007a\u005a\u0048\u0050\u0035\u0044\u0065\u0056\u007a\u006b\u0032\u002d\u007b\u0065\u005e\u0065\u002e\u0020\u002d\u0076\u0048\u007c\u0032\u0045\u0060\u0071\u0075\u0056\u0032\u006e\u007b\u0076\u0066\u0065\u0041\u0066\u0046\u0071\u0065\u006f\u003f\u0075\u0049\u006d\u004c\u0065\u0069\u005e\u0036\u0051\u0043\u0059\u0077\u0034\u002c\u0071\u003a\u005d\u0077\u002e\u0029\u0074\u0026\u0067\u0032\u007a\u006b\u0078\u0071\u003b\u0028\u002d\u004e\u0028\u007a\u0035\u0058\u0043\u006a\u0065\u003e\u0042\u0059\u006d\u0072\u0070\u0049\u0060\u007d\u0030\u0057\u004d\u0067\u007e\u0020\u0054\u0022\u0074\u005f\u0078\u0039\u003d\u002b\u0063\u0068\u007a\u004d\u003c\u007d\u0051\u0029\u0055\u005c\u006e\u0037\u0065\u0046\u003a\u005f\u0037\u006c\u0054\u0042\u004d\u0028\u0075\u0050\u003c\u007e\u0051\u005f\u007a\u003c\u002d\u0067\u003b\u0057\u005a\u0025\u0023\u0051\u004b\u0071\u002b\u007a\u005a\u005c\u002c\u0051\u0076\u004f\u002d\u006f\u0078\u0071\u0026\u0039\u0074\u003f\u0066\u0079\u0074\u0044\u002c\u005f\u0062\u0056\u0043\u0061\u0074\u0043\u0041\u0035\u0051\u003a\u0035\u0040\u0031\u0053\u0044\u0054\u0076\u002b\u0037\u004f\u003e\u0049\u0032\u0050\u005e\u0028\u004d\u0074\u002c\u0068\u0052\u007a\u006d\u0049\u0051\u0058\u0075\u0047\u0053\u002c\u0046\u002e\u0059\u0069\u0053\u007d\u0025\u0025\u0045\u0031\u0042\u002b\u006e\u003a\u002b\u004e\u0038\u003f\u0079\u0058\u0032\u007d\u0077\u0024\u0055\u0062\u0030\u006a\u007a\u003a\u004b\u0025\u0023\u003b\u0079\u004f\u007d\u0055\u002f\u002f\u0068\u0061\u007a\u0056\u0031\u007d\u002d\u0048\u002f\u0042\u0028\u0028\u003a\u002e\u0043\u0054\u003d\u007b\u0067\u0038\u003e\u007a\u004c\u007d\u007d\u004e\u0020\u0069\u0079\u0047\u0040\u0047\u003e\u006b\u004e\u005d\u007c\u0035\u0033\u0027\u006f\u003e\u0031\u0047\u004b\u0032\u007b\u005a\u006c\u007a\u004d\u005b\u0069\u0069\u0027\u0033\u0026\u0031\u0035\u003c\u007e\u002e\u006e\u005a\u003b\u0074\u006f\u005d\u0045\u0077\u0079\u0068\u0057\u0058\u0068\u0057\u0068\u0077\u003d\u0040\u0040\u0074\u0038\u0060\u006a\u0058\u007b\u0063\u0068\u004e\u006c\u0076\u004a\u007b\u0035\u004e\u002d\u0026\u0042\u0046\u0068\u004d\u0066\u006f\u0073\u007b\u0024\u0047\u006b\u007b\u0020\u0056\u0065\u0033\u006e\u0046\u0047\u0051\u0046\u0036\u0061\u0029\u0051\u0047\u002a\u0044\u0050\u006e\u0076\u0050\u002a\u002d\u0073\u0067\u003f\u0053\u002f\u0026\u0051\u0052\u0027\u0039\u004a\u0048\u0052\u0044\u007e\u0063\u0039\u0071\u0046\u0049\u0066\u0022\u0063\u0042\u004e\u0034\u0064\u0026\u002f\u004b\u0067\u0032\u005c\u0031\u0055\u0026\u0050\u002d\u0077\u0077\u006e\u0037\u005d\u005e\u003e\u006f\u003c\u002d\u0032\u006a\u0049\u0069\u0067\u0069\u007d\u0050\u0066\u0070\u0075\u007a\u0054\u004e\u0077\u007e\u0051\u005a\u0022\u006e\u0029\u0021\u0039\u0061\u0075\u0068\u002c\u0074\u007c\u004e\u0028\u004c\u0070\u005d\u006e\u0049\u006e\u007d\u0030\u0066\u004c\u004b\u0022\u0066\u0033\u0067\u0071\u0071\u004d\u003e\u005e\u0066\u005c\u0059\u003e\u0054\u003b\u002d\u0027\u0029\u0055\u0044\u0054\u004d\u002b\u007b\u006b\u003d\u007d\u0053\u0070\u0063\u006f\u005f\u007e\u0075\u0056\u003c\u002c\u0029\u004e\u0050\u005e\u0035\u002c\u0029\u002b\u004f\u006f\u007c\u0066\u0063\u0023\u0062\u0072\u0079\u004c\u005a\u0030\u0061\u004c\u007c\u007c\u0040\u0073\u0037\u002d\u004d\u0055\u0067\u0055\u002e\u0070\u0071\u007c\u0034\u0046\u0077\u004f\u0054\u004e\u0047\u003e\u0047\u003d\u0049\u0059\u0042\u0076\u0071\u003f\u002a\u006f\u005d\u0064\u006d\u005a\u0058\u0041\u0060\u005b\u0062\u005a\u006c\u0065\u005e\u0079\u0025\u006b\u002c\u0038\u005d\u005c\u0026\u007b\u007e\u0064\u007c\u0068\u0043\u003d\u005f\u0075\u0026\u0034\u002b\u0062\u003e\u005c\u004c\u004d\u0072\u007b\u003e\u0027\u0039\u0078\u004a\u0029\u0025\u0057\u0073\u0035\u0074\u0069\u0075\u002f\u002a\u0052\u0062\u007e\u004a\u005b\u0048\u0046\u006e\u0046\u002c\u0076\u0051\u0067\u0049\u0076\u0037\u004d\u0033\u006f\u0075\u0066\u005f\u0030\u0047\u0068\u0048\u0035\u0021\u0035\u0078\u007b\u0073\u0057\u0053\u0054\u006f\u0034\u0071\u0079\u0043\u002b\u0063\u0037\u0044\u002f\u0025\u0068\u005a\u0034\u0040\u0070\u002d\u0022\u0041\u0079\u007b\u0033\u0045\u0059\u0055\u0047\u002f\u005f\u0059\u0038\u0042\u002b\u0033\u0030\u0056\u002e\u0075\u007a\u005b\u0073\u004b\u007b\u005a\u007e\u0064\u0022\u005e\u0029\u0059\u0038\u0077\u006b\u004d\u0053\u0041\u0075\u004c\u005b\u004b\u005f\u0037\u0033\u0054\u005a\u0022\u002d\u0059\u0032\u0074\u0041\u004c\u0047\u0073\u0064\u005e\u002d\u0035\u005e\u002f\u006d\u002c\u0060\u0034\u006c\u0065\u007e